import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 60 The future","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 60 The future","description":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 将来表达与安排，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 59 In or out?","link":"/life/english/new-concept/book-2/unit-03/lesson-059"},"next":{"text":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","link":"/life/english/new-concept/book-2/unit-03/lesson-061"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 59 In or out?","link":"/life/english/new-concept/book-2/unit-03/lesson-059"},"next":{"text":"第二册：实践与进步 · Lesson 61 Trouble with the Hubble","link":"/life/english/new-concept/book-2/unit-03/lesson-061"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-060.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-060.md"}'),o={name:"life/english/new-concept/book-2/unit-03/lesson-060.md"};function l(r,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-60-the-future" tabindex="-1">第二册：实践与进步 · Lesson 60 The future <a class="header-anchor" href="#第二册-实践与进步-·-lesson-60-the-future" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 60 The future&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>有人根据模糊线索预言未来，听者应分辨承诺、预测和事实；练习将来表达的可信度。本课的语言观察是：will meet 可表达预测，不自动意味着确定事实；may meet 更谨慎。预测是否可信取决于来源，时态本身不提供证据。完成学习后，请写一次天气预测与实际结果，明确谁预测、如何准备、最后怎样。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>future</td><td>/ˈfjuːtʃə/</td><td>n.</td><td>未来</td><td>in the future</td></tr><tr><td>predict</td><td>/prɪˈdɪkt/</td><td>v.</td><td>预测</td><td>predict the result</td></tr><tr><td>fortune</td><td>/ˈfɔːtʃuːn/</td><td>n.</td><td>运气；命运</td><td>tell fortunes</td></tr><tr><td>promise</td><td>/ˈprɒmɪs/</td><td>n.</td><td>承诺</td><td>keep a promise</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>by evening — 到傍晚之前或时，不等于整个傍晚</li><li>make a prediction — 作出预测</li></ul><h2 id="语法讲解-将来表达与安排" tabindex="-1">语法讲解：将来表达与安排 <a class="header-anchor" href="#语法讲解-将来表达与安排" aria-label="Permalink to &quot;语法讲解：将来表达与安排&quot;">​</a></h2><p>will 加动词原形可表达预测、意愿或当场决定；be going to 常表达已有打算或基于眼前证据的判断；现在进行时可描述已经落实的个人安排。表示时刻表也可用一般现在时。它们并不是严格的一对一中文翻译。时间和条件状语从句谈将来时，通常用现在时配合主句的将来表达，而不是把每个动词都加上 will。本课应用：will meet 可表达预测，不自动意味着确定事实；may meet 更谨慎。预测是否可信取决于来源，时态本身不提供证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The guide predicted that we would see clear skies by evening.</p></blockquote><p>向导预测，到傍晚我们会看到晴朗天空。</p><p>predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>将 predicted that 弱连接，重读 clear skies；注意 by evening 的时间边界。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The guide predicted that we would see clear skies by evening. We kept our raincoats anyway. The clouds finally broke just before sunset.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一次天气预测与实际结果，明确谁预测、如何准备、最后怎样。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 will/would：He predicted that the rain ___ stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> would</p><p><strong>解析：</strong> 主句从过去视角转述未来，常用 would。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>他们因为预测晴天就丢开雨衣了吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. They kept their raincoats.</p><p><strong>解析：</strong> anyway 表尽管听到预测仍保留准备。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>promise 和 predict 的关键区别是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> promise 是承诺，predict 是预测。</p><p><strong>解析：</strong> 是否承担履行义务不同，不能仅凭 will 判断。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：将来表达与安排。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-061">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",l]]);export{p as __pageData,b as default};
